diff --git a/Source/ChavrusaText/Dependencies/CommandPalette/Sources/CommandPalette/Model/CommandShortcut.swift b/Source/ChavrusaText/Dependencies/CommandPalette/Sources/CommandPalette/Model/CommandShortcut.swift
new file mode 100644
index 00000000..ade1be58
--- /dev/null
+++ b/Source/ChavrusaText/Dependencies/CommandPalette/Sources/CommandPalette/Model/CommandShortcut.swift
@@ -0,0 +1,219 @@
+import Foundation
+import SwiftUI
+
+/// A keyboard shortcut such as ⇧⌘N: one key plus modifier keys.
+///
+/// The palette shows a command's shortcut as key caps at the trailing edge of its row, and
+/// ``commandK`` is the default shortcut that opens the palette.
+///
+/// ```swift
+/// CommandShortcut("⌘N")               // ⌘N
+/// CommandShortcut("cmd+shift+n")      // ⇧⌘N
+/// CommandShortcut("n", modifiers: [.command, .option]).displayString // "⌥⌘N"
+/// ```
+public struct CommandShortcut: Hashable, Sendable, CustomStringConvertible {
+    public var key: Key
+    public var modifiers: Modifiers
+
+    public init(_ key: Key, modifiers: Modifiers = []) {
+        self.key = key
+        self.modifiers = modifiers
+    }
+
+    /// A shortcut for a character key: `CommandShortcut("n", modifiers: .command)`.
+    public init(_ character: Character, modifiers: Modifiers) {
+        self.init(.character(Character(character.lowercased())), modifiers: modifiers)
+    }
+
+    /// Parses glyph strings (`"⇧⌘N"`, `"⌘↩"`) and words joined by `+` (`"cmd+shift+n"`,
+    /// `"ctrl+option+space"`). Modifiers may come in any order. Returns `nil` when the key is
+    /// missing or unknown, or a modifier word is not recognized.
+    public init?(_ string: String) {
+        var rest = Substring(string.trimmingCharacters(in: .whitespaces))
+        var modifiers: Modifiers = []
+
+        // Leading modifier glyphs: "⇧⌘N".
+        while let first = rest.first, let modifier = Modifiers(glyph: first) {
+            modifiers.insert(modifier)
+            rest = rest.dropFirst()
+        }
+
+        // Words: "cmd+shift+n". A single remaining character is always the key, so "⌘+" works.
+        if rest.count > 1, rest.contains("+") {
+            var parts = rest.split(separator: "+", omittingEmptySubsequences: false).map(String.init)
+            // "cmd++": the empty tail means "+" itself is the key.
+            if parts.count >= 2, parts[parts.count - 1].isEmpty, parts[parts.count - 2].isEmpty {
+                parts.removeLast(2)
+                parts.append("+")
+            }
+            guard let keyName = parts.popLast(), !keyName.isEmpty else { return nil }
+            for word in parts where !word.trimmingCharacters(in: .whitespaces).isEmpty {
+                guard let modifier = Modifiers(word: word) else { return nil }
+                modifiers.insert(modifier)
+            }
+            rest = Substring(keyName)
+        }
+
+        guard let key = Key(name: String(rest)) else { return nil }
+        self.init(key, modifiers: modifiers)
+    }
+
+    /// ⌘K, the shortcut people expect to open a command palette.
+    public static let commandK = CommandShortcut(.character("k"), modifiers: .command)
+
+    /// The shortcut as menus show it, modifiers in the order ⌃⌥⇧⌘: `"⇧⌘N"`.
+    public var displayString: String {
+        modifiers.displayString + key.displayName
+    }
+
+    /// One string per key cap: `["⇧", "⌘", "N"]`.
+    public var keyCaps: [String] {
+        Modifiers.displayOrder.compactMap { modifiers.contains($0.0) ? String($0.1) : nil } + [key.displayName]
+    }
+
+    public var description: String { displayString }
+
+    /// The same shortcut for SwiftUI's `.keyboardShortcut(_:)`.
+    public var keyboardShortcut: KeyboardShortcut {
+        KeyboardShortcut(key.keyEquivalent, modifiers: modifiers.eventModifiers)
+    }
+}
+
+// MARK: - Modifiers
+
+extension CommandShortcut {
+    /// The modifier keys of a shortcut.
+    public struct Modifiers: OptionSet, Hashable, Sendable {
+        public let rawValue: UInt8
+        public init(rawValue: UInt8) { self.rawValue = rawValue }
+
+        public static let control = Modifiers(rawValue: 1 << 0)
+        public static let option = Modifiers(rawValue: 1 << 1)
+        public static let shift = Modifiers(rawValue: 1 << 2)
+        public static let command = Modifiers(rawValue: 1 << 3)
+
+        /// The order macOS uses in menus.
+        static let displayOrder: [(Modifiers, Character)] = [
+            (.control, "⌃"), (.option, "⌥"), (.shift, "⇧"), (.command, "⌘"),
+        ]
+
+        /// `"⌃⌥⇧⌘"` for all four, in menu order.
+        public var displayString: String {
+            String(Self.displayOrder.compactMap { contains($0.0) ? $0.1 : nil })
+        }
+
+        /// SwiftUI's modifiers.
+        public var eventModifiers: EventModifiers {
+            var result: EventModifiers = []
+            if contains(.control) { result.insert(.control) }
+            if contains(.option) { result.insert(.option) }
+            if contains(.shift) { result.insert(.shift) }
+            if contains(.command) { result.insert(.command) }
+            return result
+        }
+
+        init?(glyph: Character) {
+            switch glyph {
+            case "⌘": self = .command
+            case "⇧": self = .shift
+            case "⌥": self = .option
+            case "⌃": self = .control
+            default: return nil
+            }
+        }
+
+        init?(word: String) {
+            let trimmed = word.trimmingCharacters(in: .whitespaces)
+            if trimmed.count == 1, let glyph = trimmed.first, let modifier = Modifiers(glyph: glyph) {
+                self = modifier
+                return
+            }
+            switch trimmed.lowercased() {
+            case "cmd", "command", "meta", "super": self = .command
+            case "shift": self = .shift
+            case "opt", "option", "alt": self = .option
+            case "ctrl", "control", "ctl": self = .control
+            default: return nil
+            }
+        }
+    }
+}
+
+// MARK: - Keys
+
+extension CommandShortcut {
+    /// The key of a shortcut.
+    public enum Key: Hashable, Sendable, CustomStringConvertible {
+        /// A key that types a character, stored lowercased: `"n"`, `","`, `"1"`.
+        case character(Character)
+        case returnKey
+        case escape
+        case delete
+        case tab
+        case space
+        case upArrow
+        case downArrow
+        case leftArrow
+        case rightArrow
+
+        /// A key by name or glyph: `"n"`, `"N"`, `","`, `"return"`, `"↩"`, `"esc"`, `"⌫"`,
+        /// `"space"`, `"up"`, `"↑"`.
+        public init?(name: String) {
+            if name == " " {
+                self = .space
+                return
+            }
+            let trimmed = name.trimmingCharacters(in: .whitespaces)
+            switch trimmed.lowercased() {
+            case "return", "enter", "↩", "⏎": self = .returnKey
+            case "esc", "escape", "⎋": self = .escape
+            case "delete", "backspace", "⌫": self = .delete
+            case "tab", "⇥": self = .tab
+            case "space", "␣": self = .space
+            case "up", "uparrow", "↑": self = .upArrow
+            case "down", "downarrow", "↓": self = .downArrow
+            case "left", "leftarrow", "←": self = .leftArrow
+            case "right", "rightarrow", "→": self = .rightArrow
+            default:
+                guard trimmed.count == 1, let character = trimmed.first,
+                      !character.isWhitespace, Modifiers(glyph: character) == nil
+                else { return nil }
+                self = .character(Character(character.lowercased()))
+            }
+        }
+
+        /// How the key is shown: `"N"`, `","`, `"↩"`, `"Space"`.
+        public var displayName: String {
+            switch self {
+            case .character(let character): character.uppercased()
+            case .returnKey: "↩"
+            case .escape: "⎋"
+            case .delete: "⌫"
+            case .tab: "⇥"
+            case .space: "Space"
+            case .upArrow: "↑"
+            case .downArrow: "↓"
+            case .leftArrow: "←"
+            case .rightArrow: "→"
+            }
+        }
+
+        public var description: String { displayName }
+
+        /// SwiftUI's key equivalent.
+        public var keyEquivalent: KeyEquivalent {
+            switch self {
+            case .character(let character): KeyEquivalent(character)
+            case .returnKey: .return
+            case .escape: .escape
+            case .delete: .delete
+            case .tab: .tab
+            case .space: .space
+            case .upArrow: .upArrow
+            case .downArrow: .downArrow
+            case .leftArrow: .leftArrow
+            case .rightArrow: .rightArrow
+            }
+        }
+    }
+}

diff --git a/Source/ChavrusaText/Dependencies/CommandPalette/Sources/CommandPalette/Recents/RecentCommands.swift b/Source/ChavrusaText/Dependencies/CommandPalette/Sources/CommandPalette/Recents/RecentCommands.swift
new file mode 100644
index 00000000..4e81cef9
--- /dev/null
+++ b/Source/ChavrusaText/Dependencies/CommandPalette/Sources/CommandPalette/Recents/RecentCommands.swift
@@ -0,0 +1,151 @@
+import Combine
+import Foundation
+
+/// The ids of recently run commands, newest first, without duplicates and at most `limit` long.
+///
+/// A plain value with the rules; ``RecentCommandsStore`` keeps one and saves it.
+public struct RecentCommands: Hashable, Sendable {
+    /// Newest first.
+    public private(set) var ids: [String]
+    /// How many ids are kept.
+    public let limit: Int
+
+    public init(ids: [String] = [], limit: Int = 5) {
+        self.limit = max(0, limit)
+        var seen = Set<String>()
+        self.ids = Array(ids.filter { seen.insert($0).inserted }.prefix(self.limit))
+    }
+
+    /// Moves `id` to the front, adding it when it is new and dropping the oldest beyond the limit.
+    public mutating func record(_ id: String) {
+        ids.removeAll { $0 == id }
+        ids.insert(id, at: 0)
+        if ids.count > limit {
+            ids.removeLast(ids.count - limit)
+        }
+    }
+
+    /// Forgets `id`.
+    public mutating func remove(_ id: String) {
+        ids.removeAll { $0 == id }
+    }
+
+    /// Forgets everything.
+    public mutating func removeAll() {
+        ids.removeAll()
+    }
+
+    /// The commands for the recent ids, newest first. Ids of commands that no longer exist are skipped.
+    public func commands(from commands: [Command]) -> [Command] {
+        ids.compactMap { id in commands.first { $0.id == id } }
+    }
+}
+
+// MARK: - Storage
+
+/// Where ``RecentCommandsStore`` keeps the recent ids. Inject your own to store them elsewhere, or
+/// ``InMemoryRecentCommandsStorage`` in tests and previews.
+@MainActor
+public protocol RecentCommandsStorage: AnyObject {
+    func loadRecentCommandIDs() -> [String]
+    func saveRecentCommandIDs(_ ids: [String])
+}
+
+/// Keeps the recent ids in `UserDefaults` as an array of strings.
+@MainActor
+public final class UserDefaultsRecentCommandsStorage: RecentCommandsStorage {
+    public let key: String
+    private let defaults: UserDefaults
+
+    public init(key: String = "CommandPalette.recentCommandIDs", defaults: UserDefaults = .standard) {
+        self.key = key
+        self.defaults = defaults
+    }
+
+    public func loadRecentCommandIDs() -> [String] {
+        defaults.stringArray(forKey: key) ?? []
+    }
+
+    public func saveRecentCommandIDs(_ ids: [String]) {
+        defaults.set(ids, forKey: key)
+    }
+}
+
+/// Keeps the recent ids in memory only. For tests, previews and screenshots.
+@MainActor
+public final class InMemoryRecentCommandsStorage: RecentCommandsStorage {
+    /// What was saved last, or the initial ids.
+    public private(set) var ids: [String]
+    /// How often the store saved.
+    public private(set) var saveCount = 0
+
+    public init(_ ids: [String] = []) {
+        self.ids = ids
+    }
+
+    public func loadRecentCommandIDs() -> [String] {
+        ids
+    }
+
+    public func saveRecentCommandIDs(_ ids: [String]) {
+        self.ids = ids
+        saveCount += 1
+    }
+}
+
+// MARK: - Store
+
+/// Remembers which commands were run, so the palette can list them under "Recent" when the
+/// search field is empty.
+///
+/// ```swift
+/// let recents = RecentCommandsStore()                       // UserDefaults, 5 commands
+/// let recents = RecentCommandsStore(storage: InMemoryRecentCommandsStorage(), limit: 3)
+/// recents.record(command)                                   // done by the palette when it runs one
+/// recents.ids                                               // newest first
+/// ```
+@MainActor
+public final class RecentCommandsStore: ObservableObject {
+    /// The store the palette uses when you pass none: `UserDefaults.standard`, 5 commands.
+    public static let shared = RecentCommandsStore()
+
+    @Published public private(set) var recents: RecentCommands
+    private let storage: any RecentCommandsStorage
+
+    public init(storage: (any RecentCommandsStorage)? = nil, limit: Int = 5) {
+        let storage = storage ?? UserDefaultsRecentCommandsStorage()
+        self.storage = storage
+        self.recents = RecentCommands(ids: storage.loadRecentCommandIDs(), limit: limit)
+    }
+
+    /// Newest first.
+    public var ids: [String] { recents.ids }
+
+    /// Moves the command to the front of the recent commands and saves.
+    public func record(_ command: Command) {
+        record(id: command.id)
+    }
+
+    /// Moves the command with this id to the front of the recent commands and saves.
+    public func record(id: String) {
+        recents.record(id)
+        storage.saveRecentCommandIDs(recents.ids)
+    }
+
+    /// Forgets one command and saves.
+    public func remove(id: String) {
+        recents.remove(id)
+        storage.saveRecentCommandIDs(recents.ids)
+    }
+
+    /// Forgets all recent commands and saves.
+    public func clear() {
+        recents.removeAll()
+        storage.saveRecentCommandIDs(recents.ids)
+    }
+
+    /// The recent commands among `commands`, newest first.
+    public func commands(from commands: [Command]) -> [Command] {
+        recents.commands(from: commands)
+    }
+}

diff --git a/Source/ChavrusaText/Dependencies/CommandPalette/Sources/CommandPalette/Search/CommandPaletteResults.swift b/Source/ChavrusaText/Dependencies/CommandPalette/Sources/CommandPalette/Search/CommandPaletteResults.swift
