+            .onChange(of: manager.openTabs.map(\.id)) { _, _ in workspace?.synchronize(manager) }
+            .onChange(of: manager.activeTabId) { _, _ in workspace?.synchronize(manager) }
+            .onChange(of: workspace?.selection?.groupID) { _, _ in
